def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    marker = next(value for value, _ in counts.most_common() if value != background)
    out = [row[:] for row in grid]
    for r in range(h):
        positions = [c for c, value in enumerate(grid[r]) if value == marker]
        if len(positions) >= 2:
            for c in range(min(positions) + 1, max(positions)):
                if grid[r][c] == background:
                    out[r][c] = 3
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        if len(positions) >= 2:
            for r in range(min(positions) + 1, max(positions)):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out
